727	import Link from "next/link";
728	
729	/**
730	 * Minimal-Markup für Ratgeber-Inhalte (bewusst kein Markdown-Parser, kein
731	 * dangerouslySetInnerHTML):
732	 *   **fett**
733	 *   [Linktext](/interner/pfad)   -> next/link
734	 *   [Linktext](https://…)        -> externer Link, neuer Tab, rel="noopener"
735	 */
736	const MUSTER = /(\*\*[^*]+\*\*|\[[^\]]+\]\([^)\s]+\))/g;
737	
738	export default function InlineText({ text }) {
739	  if (text == null) return null;
740	  const teile = String(text).split(MUSTER).filter((t) => t !== "");
741	
742	  return teile.map((teil, i) => {
743	    if (teil.startsWith("**") && teil.endsWith("**")) {
744	      const innen = teil.slice(2, -2);
745	      return <strong key={i}>{innen.includes("](") ? <InlineText text={innen} /> : innen}</strong>;
746	    }
747	    const link = teil.match(/^\[([^\]]+)\]\(([^)\s]+)\)$/);
748	    if (link) {
749	      const [, label, href] = link;
750	      const klasse = "font-medium text-ov-700 underline decoration-ov-300 underline-offset-[3px] transition-colors hover:decoration-current";
751	      if (/^https?:\/\//.test(href)) {
752	        return (
753	          <a key={i} href={href} target="_blank" rel="noopener noreferrer" className={klasse}>
754	            {label}
755	          </a>
756	        );
757	      }
758	      return (
759	        <Link key={i} href={href} className={klasse}>
760	          {label}
761	        </Link>
762	      );
763	    }
764	    return teil;
765	  });
766	}
