768	/** Klartext ohne Markup – für Schema.org, Meta-Beschreibungen und Wortzählung. */
769	export function klartext(text) {
770	  return String(text ?? "")
771	    .replace(/\*\*([^*]+)\*\*/g, "$1")
772	    .replace(/\[([^\]]+)\]\([^)\s]+\)/g, "$1");
773	}
