const KAT = ["Fläche & Pacht","Agri-PV & Landwirtschaft","Investieren & Projektbörse","Recht & Genehmigung","Strom, Markt & Gemeinschaft"];
const woerter = (x) => typeof x === "string" ? x.replace(/\[([^\]]+)\]\([^)]+\)/g, "$1").split(/\s+/).filter(Boolean).length : Array.isArray(x) ? x.reduce((s, y) => s + woerter(y), 0) : x && typeof x === "object" ? Object.entries(x).reduce((s, [k, v]) => (["id","typ","variant","href","url"].includes(k) ? s : s + woerter(v)), 0) : 0;
function links(x, out = []) { if (typeof x === "string") { for (const m of x.matchAll(/\]\((\/[^)\s]*)\)/g)) out.push(m[1]); } else if (Array.isArray(x)) x.forEach((y) => links(y, out)); else if (x && typeof x === "object") { for (const [k, v] of Object.entries(x)) { if (k === "href" && typeof v === "string" && v.startsWith("/")) out.push(v); else links(v, out); } } return out; }
for (const a of INHALTE) {
  const w = woerter([a.kurzFazit, a.abschnitte, a.faq]);
  const probleme = [];
  const text = JSON.stringify(a);
  if (/undefined|NaN/.test(text)) probleme.push("undefined/NaN");
  if (!KAT.includes(a.kategorie)) probleme.push("Kategorie " + a.kategorie);
  if (!a.bild?.startsWith("/img/") || !fs.existsSync(R + "public" + a.bild)) probleme.push("Bild " + a.bild);
  if ((a.seoTitle || "").length > 60) probleme.push("seoTitle " + a.seoTitle.length);
  if (a.description.length < 130 || a.description.length > 165) probleme.push("desc " + a.description.length);
  if (w < 1500 || w > 3100) probleme.push("Wörter " + w);
  const tab = a.abschnitte.flatMap((s) => s.bloecke).filter((b) => b.typ === "tabelle").length;
  if (tab < 2) probleme.push("Tabellen " + tab);
  if ((a.faq || []).length < 5) probleme.push("FAQ " + (a.faq || []).length);
  if ((a.quellen || []).length < 4) probleme.push("Quellen " + (a.quellen || []).length);
  for (const l of links(a)) {
    const [pfad, anker] = l.split("#");
    if (pfad.startsWith("/ratgeber/")) { if (!slugs.has(pfad.slice(10))) probleme.push("Ratgeber? " + l); }
    else if (!ROUTEN.has(pfad)) probleme.push("Route? " + l);
    if (pfad === "/wissen/lexikon" && anker && !ids.has(anker)) probleme.push("Lexikon? " + anker);
  }
  const intern = a.abschnitte.flatMap((s) => links(s.bloecke)).length;
  console.log(`${a.slug.padEnd(40)} ${String(w).padStart(5)} W  intern:${intern}  ${probleme.join("; ")}`);
}
// Lexikon-Links
for (const b of BEGRIFFE) { if (b.link) { const p = b.link.href.split("#")[0]; if (p.startsWith("/ratgeber/") ? !slugs.has(p.slice(10)) : !ROUTEN.has(p)) console.log("LEXLINK?", b.id, b.link.href); } (b.verwandt||[]).forEach(v=>!ids.has(v)&&console.log("VERWANDT?",b.id,v)); }
console.log(INHALTE.length, "Artikel,", BEGRIFFE.length, "Begriffe");
EOF
